with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (61, 'Do you prefer big cities or small towns?', 'Você prefere cidades grandes ou cidades pequenas?', '[{"answer":"I prefer big cities.","translation":"Eu prefiro cidades grandes.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I like small towns better.","translation":"Eu gosto mais de cidades pequenas.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Big cities are more convenient for me.","translation":"Cidades grandes são mais convenientes para mim.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I prefer small towns because they''re quieter.","translation":"Eu prefiro cidades pequenas porque são mais tranquilas.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I like living in a medium-sized city because it offers a balance.","translation":"Eu gosto de morar em uma cidade de médio porte porque oferece equilíbrio.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (62, 'What is your favorite city?', 'Qual é a sua cidade favorita?', '[{"answer":"My favorite city is São Paulo.","translation":"Minha cidade favorita é São Paulo.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like Rio de Janeiro.","translation":"Eu gosto muito do Rio de Janeiro.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Lisbon is one of my favorite cities.","translation":"Lisboa é uma das minhas cidades favoritas.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I don''t have a favorite city yet.","translation":"Eu ainda não tenho uma cidade favorita.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I love my hometown because my family and friends are there.","translation":"Eu adoro minha cidade natal porque minha família e meus amigos estão lá.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (63, 'What do you like about the city where you live?', 'O que você gosta na cidade onde mora?', '[{"answer":"I like the parks and restaurants.","translation":"Eu gosto dos parques e restaurantes.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I like that it''s easy to get around.","translation":"Eu gosto do fato de ser fácil se locomover.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"The city has good services and many things to do.","translation":"A cidade tem bons serviços e muitas coisas para fazer.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I like the people and the relaxed atmosphere.","translation":"Eu gosto das pessoas e do clima tranquilo.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"What I like most is that it''s big enough to have options but not too crowded.","translation":"O que mais gosto é que ela é grande o suficiente para ter opções, mas não é lotada demais.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (64, 'Would you like to live in another country?', 'Você gostaria de morar em outro país?', '[{"answer":"Yes, I''d like to live abroad someday.","translation":"Sim, eu gostaria de morar fora do país algum dia.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Maybe, for a few years.","translation":"Talvez, por alguns anos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d like to experience living in Canada.","translation":"Eu gostaria de experimentar morar no Canadá.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"No, I''m happy living in Brazil.","translation":"Não, eu estou feliz morando no Brasil.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I would consider it if I had a good job opportunity.","translation":"Eu consideraria isso se tivesse uma boa oportunidade de trabalho.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (65, 'What is your favorite day of the week?', 'Qual é o seu dia favorito da semana?', '[{"answer":"Friday is my favorite day.","translation":"Sexta-feira é o meu dia favorito.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I like Saturday best.","translation":"Eu gosto mais de sábado.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Sunday is my favorite because I can relax.","translation":"Domingo é o meu favorito porque posso relaxar.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I actually like Monday because I enjoy starting a new week.","translation":"Na verdade, eu gosto de segunda-feira porque gosto de começar uma nova semana.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Probably Saturday, because I have more time for family and friends.","translation":"Provavelmente sábado, porque tenho mais tempo para família e amigos.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (66, 'What is your favorite season?', 'Qual é a sua estação do ano favorita?', '[{"answer":"Summer is my favorite season.","translation":"O verão é a minha estação favorita.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I prefer winter.","translation":"Eu prefiro o inverno.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I love spring because the weather is pleasant.","translation":"Eu adoro a primavera porque o clima é agradável.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Autumn is my favorite because I like cooler days.","translation":"O outono é o meu favorito porque gosto de dias mais frescos.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I usually prefer spring, but it depends on where I am.","translation":"Eu geralmente prefiro a primavera, mas depende de onde estou.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (67, 'What is your favorite holiday?', 'Qual é o seu feriado favorito?', '[{"answer":"Christmas is my favorite holiday.","translation":"O Natal é o meu feriado favorito.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like New Year''s Day.","translation":"Eu gosto muito do Ano-Novo.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"My favorite holiday is Carnival.","translation":"Meu feriado favorito é o Carnaval.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I like holidays when my whole family gets together.","translation":"Eu gosto de feriados em que toda a minha família se reúne.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Christmas is probably my favorite because of the family traditions.","translation":"O Natal provavelmente é o meu favorito por causa das tradições familiares.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (68, 'What do you usually do on weekends?', 'O que você costuma fazer nos fins de semana?', '[{"answer":"I usually relax at home.","translation":"Eu geralmente relaxo em casa.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I spend time with my family.","translation":"Eu passo tempo com minha família.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I go out with friends.","translation":"Eu saio com amigos.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I usually exercise and do things around the house.","translation":"Eu geralmente faço exercícios e cuido de coisas em casa.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I try to rest, meet friends, and prepare for the next week.","translation":"Eu tento descansar, encontrar amigos e me preparar para a próxima semana.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (69, 'What did you do last weekend?', 'O que você fez no fim de semana passado?', '[{"answer":"I stayed home and relaxed.","translation":"Eu fiquei em casa e relaxei.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I visited my family.","translation":"Eu visitei minha família.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I went out with some friends.","translation":"Eu saí com alguns amigos.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I watched a movie and cooked dinner.","translation":"Eu assisti a um filme e preparei o jantar.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I had a busy weekend: I cleaned the house, exercised, and met some friends.","translation":"Eu tive um fim de semana corrido: limpei a casa, fiz exercícios e encontrei alguns amigos.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (70, 'What are you going to do next weekend?', 'O que você vai fazer no próximo fim de semana?', '[{"answer":"I''m going to stay home and rest.","translation":"Eu vou ficar em casa e descansar.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m going to visit my parents.","translation":"Eu vou visitar meus pais.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''m meeting some friends on Saturday.","translation":"Eu vou encontrar alguns amigos no sábado.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I plan to go to the movies.","translation":"Eu planejo ir ao cinema.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I haven''t decided yet, but I''d like to do something outdoors.","translation":"Eu ainda não decidi, mas gostaria de fazer algo ao ar livre.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions as question
set question_text=content.question_text,question_translation=content.question_translation,answer_examples=content.answer_examples
from card_content content where question.display_order=content.display_order;
